// ספרות פאי - 2000 ספרות אחרי הנקודה העשרונית
// π = 3.1415926535897932384626433832795...

export const PI_DIGITS = '';

// פונקציה לקבלת טווח ספרות
export const getDigitRange = (start: number, end: number): string => {
  return PI_DIGITS.slice(start, end);
};

// פונקציה לקבלת ספרה בודדת
export const getDigitAt = (index: number): string => {
  return PI_DIGITS[index] || '?';
};

// פונקציה לפורמט ספרות לקבוצות
export const formatDigits = (
  digits: string,
  groupSize: number = 1,
  separator: string = ' '
): string => {
  const groups: string[] = [];
  for (let i = 0; i < digits.length; i += groupSize) {
    groups.push(digits.slice(i, i + groupSize));
  }
  return groups.join(separator);
};

// הוספת הנקודה העשרונית ל-3
export const getFullPiString = (numDigits: number): string => {
  return '3.' + PI_DIGITS.slice(0, numDigits);
};

// סה"כ ספרות זמינות
export const TOTAL_DIGITS = PI_DIGITS.length;

// פורמטים נפוצים
export const PiFormats = {
  SINGLE: 1,      // 1 4 1 5 9 2 6
  PAIRS: 2,       // 14 15 92 65
  QUADS: 4,       // 1415 9265
  OCTET: 8,       // 14159265
  NINE: 9,        // 141592653
  TEN: 10,        // 1415926535
} as const;

export type PiFormat = typeof PiFormats[keyof typeof PiFormats];
